public int exportToText() {
    String folderName;
    if (!BackupUtils.externalStorageAvailable()) {
        Log.d(BackupUtils.TAG, "Media was not mounted");
        return 0;
    }
    PrintStream ps = getExportToTextPrintStream();
    if (ps == null) {
        Log.e(BackupUtils.TAG, "get print stream error");
        return 3;
    }
    Cursor folderCursor = this.mContext.getContentResolver().query(Notes.CONTENT_NOTE_URI, NOTE_PROJECTION, "(type=1 AND parent_id<>-3) OR _id=-2", null, null);
    if (folderCursor != null) {
        if (folderCursor.moveToFirst()) {
            do {
                if (folderCursor.getLong(0) == -2) {
                    folderName = this.mContext.getString(R.string.call_record_folder_name);
                } else {
                    folderName = folderCursor.getString(2);
                }
                if (!TextUtils.isEmpty(folderName)) {
                    ps.println(String.format(getFormat(0), folderName));
                }
                String folderId = folderCursor.getString(0);
                exportFolderToText(folderId, ps);
            } while (folderCursor.moveToNext());
        }
        folderCursor.close();
    }
    Cursor noteCursor = this.mContext.getContentResolver().query(Notes.CONTENT_NOTE_URI, NOTE_PROJECTION, "type=0 AND parent_id=0", null, null);
    if (noteCursor != null) {
        if (noteCursor.moveToFirst()) {
            do {
                ps.println(String.format(getFormat(1), DateFormat.format(this.mContext.getString(R.string.format_datetime_mdhm), noteCursor.getLong(1))));
                String noteId = noteCursor.getString(0);
                exportNoteToText(noteId, ps);
            } while (noteCursor.moveToNext());
        }
        noteCursor.close();
    }
    ps.close();
    return 4;
}
